def cube(color_edges=None):
    ed = [['A', 'B'], ['B', 'C'], ['C', 'D'], ['D', 'A'], ['A′', 'B′'], ['B′', 'C′'], ['C′', 'D′'], ['D′', 'A′'], ['A', 'A′'], ['B', 'B′'], ['C', 'C′'], ['D', 'D′']]
    cfg = dict(CUBE); cfg['segments'] = [([e[0], e[1], color_edges[tuple(e)]] if color_edges and tuple(e) in color_edges else e) for e in ed]; return cfg
