def lvl(P):
    nm, kd = P['sk']; c = S.count(nm, kd); f = str
    o1 = M4(1, 'How many pairs of edges of %s are %s?' % (S.NM[nm][0], S.KN[kd][0]), 'Có bao nhiêu cặp cạnh của %s %s?' % (S.NM[nm][1], S.KN[kd][1]), f(c), [f(c + 1), f(c - 1), f(2 * c)], 'Check each pair of edges.', 'Xét từng cặp cạnh.')
    x, y = P['mid']; o2 = M4(2, 'In the pyramid, M and N are the midpoints of SA and SB. If AB = %d, then MN = …' % x, 'Trong hình chóp, M, N là trung điểm của SA, SB. Nếu AB = %d thì MN = …' % x, f(x // 2), [f(x), f(2 * x), f(x // 2 + 2)], 'Midline: \\(MN=\\dfrac12AB\\).', 'Đường trung bình: \\(MN=\\dfrac12AB\\).')
    a, b = P['ab']; o3 = M4(3, 'In the tetrahedron ABCD, M, N, P, Q are the midpoints of AB, BC, CD, DA. If AC = %d and BD = %d, the perimeter of MNPQ is…' % (a, b), 'Cho tứ diện ABCD, M, N, P, Q là trung điểm của AB, BC, CD, DA. Nếu AC = %d, BD = %d thì chu vi MNPQ là…' % (a, b), f(a + b), [f((a + b) // 2), f(2 * (a + b)), f(a * b // 2), f(a + b + 2)], 'Perimeter \\(=AC+BD\\).', 'Chu vi \\(=AC+BD\\).')
    st4 = [('Two lines with no common point are always parallel.', 'Hai đường thẳng không có điểm chung thì luôn song song.', False), ('Two skew lines have no common point.', 'Hai đường thẳng chéo nhau thì không có điểm chung.', True), ('If \\(a\\parallel c\\) and \\(b\\parallel c\\), then \\(a\\parallel b\\) (or they are the same line).', 'Nếu \\(a\\parallel c\\) và \\(b\\parallel c\\) thì \\(a\\parallel b\\) (hoặc trùng nhau).', True)][P['s4']]
    t4 = tf(4, st4[0], st4[1], st4[2], 'Parallel lines need a common plane; skew lines have none.', 'Hai đường thẳng song song phải cùng mặt phẳng; hai đường chéo nhau thì không.')
    st5 = [('Through a point outside a line there are infinitely many parallel lines to it.', 'Qua một điểm ngoài đường thẳng có vô số đường thẳng song song với đường thẳng đó.', False), ('In a cube, AB and CC′ are skew.', 'Trong hình lập phương, AB và CC′ chéo nhau.', True), ('In a cube, AB and DD′ are intersecting.', 'Trong hình lập phương, AB và DD′ cắt nhau.', False)][P['s5']]
    t5 = tf(5, st5[0], st5[1], st5[2], 'Check: exactly one parallel line through a point outside; AB, CC′ are not coplanar; AB, DD′ are skew.', 'Kiểm tra: qua một điểm ngoài có đúng một đường song song; AB, CC′ không đồng phẳng; AB, DD′ chéo nhau.')
    nm2, kd2 = P['sk2']; s6 = sh(6, 'How many pairs of edges of %s are %s?' % (S.NM[nm2][0], S.KN[kd2][0]), 'Có bao nhiêu cặp cạnh của %s %s?' % (S.NM[nm2][1], S.KN[kd2][1]), S.count(nm2, kd2), 'Check each pair of edges.', 'Xét từng cặp cạnh.')
    p, q = P['pq']; s7 = sh(7, 'In the tetrahedron ABCD, AC ⊥ BD, AC = %d, BD = %d; M, N, P, Q are the midpoints of AB, BC, CD, DA. Find the area of MNPQ.' % (p, q), 'Cho tứ diện ABCD có AC ⊥ BD, AC = %d, BD = %d; M, N, P, Q là trung điểm AB, BC, CD, DA. Tính diện tích MNPQ.' % (p, q), p * q // 4, 'MNPQ is a rectangle with sides \\(\\frac{AC}2\\), \\(\\frac{BD}2\\).', 'MNPQ là hình chữ nhật có hai cạnh \\(\\frac{AC}2\\), \\(\\frac{BD}2\\).')
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
